create table if not exists public.customers (id uuid primary key default gen_random_uuid(), customer_code text unique, full_name text not null, email text, phone text, country text, notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.customers enable row level security;
drop policy if exists "CRM staff read customers" on public.customers; create policy "CRM staff read customers" on public.customers for select to authenticated using (public.is_crm_staff());
drop policy if exists "CRM staff add customers" on public.customers; create policy "CRM staff add customers" on public.customers for insert to authenticated with check (public.is_crm_staff() and public.current_user_role() in ('admin','manager','agent'));
drop policy if exists "CRM authorized update customers" on public.customers; create policy "CRM authorized update customers" on public.customers for update to authenticated using (public.is_crm_staff() and public.current_user_role() in ('admin','manager','agent')) with check (public.is_crm_staff() and public.current_user_role() in ('admin','manager','agent'));
drop policy if exists "CRM admins delete customers" on public.customers; create policy "CRM admins delete customers" on public.customers for delete to authenticated using (public.current_user_role()='admin');
